    Point3<ObjectSpace> point);

enum class GeometryError {
    InvalidInput,
    DegenerateDirection,
    SingularSystem,
    IllConditioned,
    NonManifoldTopology
};

struct PlaneIntersection {
    Vec3 point;
    Vec3 direction;
};

